/* ------------------------------------------------------------------ */
/* Backend connection — the mailbox sync service (see /backend). If    */
/* it isn't reachable (e.g. previewing this file standalone), the app  */
/* falls back to the built-in demo reports below so the UI still works.*/
/*                                                                      */
/* API_BASE auto-detects the backend's actual port instead of assuming */
/* it's always 5000 — useful when API_PORT is changed in .env/Settings,*/
/* when 5000 is already taken by something else, or when running       */
/* multiple instances side by side. Detection result is cached in      */
/* localStorage so repeat visits skip straight to the right port.      */
/* ------------------------------------------------------------------ */


const API_BASE_STORAGE_KEY = "taxilla_api_base";
const API_BASE_DEFAULT = "http://localhost:5000";
let API_BASE = (() => {
  try {
    return localStorage.getItem(API_BASE_STORAGE_KEY) || API_BASE_DEFAULT;
  } catch {
    return API_BASE_DEFAULT;
  }
})();

let _apiBaseDetectPromise = null;

async function _pingHealth(base, timeoutMs = 1200) {
  try {
    const res = await fetch(`${base}/api/health`, { signal: AbortSignal.timeout(timeoutMs) });
    return res.ok;
  } catch {
    return false;
  }
}

/** Candidate ports to probe, in priority order — 5000 first since that's
 * the documented default (config.py's API_PORT), then a few common
 * fallbacks someone might set API_PORT to. */
function _candidateBases() {
  const ports = [5000, 5001, 5002, 5050, 8000, 8080];
  const hosts = ["http://localhost", "http://127.0.0.1"];
  const bases = [];
  for (const host of hosts) for (const port of ports) bases.push(`${host}:${port}`);
  return bases;
}

/** Resolves the real backend base URL once, caching the result. Safe to
 * call many times — concurrent callers share the same in-flight probe. */
async function ensureApiBase() {
  if (_apiBaseDetectPromise) return _apiBaseDetectPromise;
  _apiBaseDetectPromise = (async () => {
    // Fast path: whatever we're already using (cached or default) still works.
    if (await _pingHealth(API_BASE)) return API_BASE;

    // Same-origin path: if Flask is serving this frontend itself (the
    // single-server / production setup — see backend/app.py's
    // serve_frontend route), "" (relative URLs) reaches it directly with
    // no port-guessing needed at all.
    if (typeof window !== "undefined" && (await _pingHealth(""))) {
      API_BASE = "";
      try {
        localStorage.setItem(API_BASE_STORAGE_KEY, "");
      } catch {
        /* localStorage unavailable — detection just won't be cached */
      }
      return API_BASE;
    }

    // Slow path: probe common host/port combinations in parallel and take
    // whichever answers first. This is the two-dev-server case (frontend
    // on 5173 via `npm run dev`, backend separately on 5000 or similar).
    const candidates = _candidateBases().filter((b) => b !== API_BASE);
    const found = await new Promise((resolve) => {
      let remaining = candidates.length;
      if (remaining === 0) return resolve(null);
      candidates.forEach(async (base) => {
        const ok = await _pingHealth(base);
        if (ok) resolve(base);
        remaining -= 1;
        if (remaining === 0) resolve(null);
      });
    });

    if (found) {
      API_BASE = found;
      try {
        localStorage.setItem(API_BASE_STORAGE_KEY, found);
      } catch {
        /* localStorage unavailable — detection just won't be cached */
      }
    }
    // Nothing responded: keep the existing value so callers still get a
    // clear "unreachable" result from apiHealth() rather than a thrown error.
    return API_BASE;
  })();
  return _apiBaseDetectPromise;
}

/** Every backend call should go through this instead of building the URL
 * off the raw API_BASE constant, so it always targets the detected port. */
async function apiFetch(path, options) {
  await ensureApiBase();
  return fetch(`${API_BASE}${path}`, options);
}

