/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
function fileExt(name) {
  const m = /\.([a-zA-Z0-9]+)$/.exec(name || "");
  return m ? m[1].toLowerCase() : "";
}

function fmtSize(bytes) {
  if (bytes < 1024) return bytes + " B";
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(0) + " KB";
  return (bytes / (1024 * 1024)).toFixed(1) + " MB";
}

function nowTime() {
  return new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

// Best-effort: turn a sheet's array-of-arrays into a header row + records,
// tolerating title rows / merged headers that don't start at row 1.
function aoaToRecords(aoa) {
  let headerIdx = 0;
  for (let i = 0; i < Math.min(aoa.length, 15); i++) {
    const row = aoa[i] || [];
    const nonEmpty = row.filter((c) => c !== null && c !== undefined && String(c).trim() !== "");
    if (nonEmpty.length >= 2) { headerIdx = i; break; }
  }
  const header = (aoa[headerIdx] || []).map((h, i) => (h === null || h === undefined || h === "" ? `Col${i + 1}` : String(h).trim()));
  const records = [];
  for (let i = headerIdx + 1; i < aoa.length; i++) {
    const row = aoa[i] || [];
    if (row.every((c) => c === null || c === undefined || String(c).trim() === "")) continue;
    const rec = {};
    header.forEach((h, idx) => (rec[h] = row[idx] !== undefined ? row[idx] : null));
    records.push(rec);
  }
  return { header, records };
}

function recordsToCsv(header, records, maxRows = 40) {
  const lines = [header.join(",")];
  records.slice(0, maxRows).forEach((r) => {
    lines.push(header.map((h) => JSON.stringify(r[h] ?? "")).join(","));
  });
  return lines.join("\n");
}

async function parseSpreadsheetFile(file) {
  const ext = fileExt(file.name);
  if (ext === "csv" || ext === "tsv") {
    const text = await file.text();
    const parsed = Papa.parse(text, { header: false });
    const { header, records } = aoaToRecords(parsed.data);
    return { sheets: { Sheet1: records }, csvContext: `${file.name}\nSheet1\n` + recordsToCsv(header, records) };
  }
  if (ext === "xlsx" || ext === "xls") {
    const buf = await file.arrayBuffer();
    const wb = XLSX.read(buf, { type: "array" });
    const sheets = {};
    let ctxParts = [];
    wb.SheetNames.slice(0, 6).forEach((name) => {
      const ws = wb.Sheets[name];
      const aoa = XLSX.utils.sheet_to_json(ws, { header: 1, raw: true, defval: null });
      const { header, records } = aoaToRecords(aoa);
      sheets[name] = records;
      ctxParts.push(`Sheet: ${name}\n` + recordsToCsv(header, records));
    });
    return { sheets, csvContext: `${file.name}\n` + ctxParts.join("\n\n") };
  }
  return { sheets: null, csvContext: null };
}

function autoChartFromSheets(sheets) {
  if (!sheets) return null;
  for (const name of Object.keys(sheets)) {
    const rows = sheets[name];
    if (!rows || !rows.length) continue;
    const keys = Object.keys(rows[0] || {});
    const numericKey = keys.find((k) => rows.every((r) => r[k] === null || r[k] === "" || !isNaN(parseFloat(r[k]))) && rows.some((r) => r[k] !== null && r[k] !== ""));
    const labelKey = keys.find((k) => k !== numericKey && rows.every((r) => typeof r[k] !== "number"));
    if (numericKey && labelKey && rows.length <= 12) {
      return {
        type: rows.length <= 6 ? "pie" : "bar",
        title: `${name} — ${numericKey} by ${labelKey}`,
        data: rows.map((r) => ({ name: String(r[labelKey]), value: parseFloat(r[numericKey]) || 0 })).filter((d) => d.name && d.name !== "null"),
      };
    }
  }
  return null;
}

