/* ------------------------------------------------------------------ */
/* Anthropic call — answers grounded ONLY in the attached report data  */
/* ------------------------------------------------------------------ */
function buildSystemPrompt(context) {
  return `You are the TAXILLA AI Assistant, embedded in a compliance/reporting chatbot.
Answer the user's question primarily in clear text format based ONLY on the attached report data provided below.
Provide a concise, direct text response (cite specific numbers, names, or values).

ONLY include chartData if the user's prompt explicitly requests a chart/graph/breakdown OR if numeric comparative metrics (e.g. category totals, regional sales, headcounts) can be derived from the prompt. For general text queries or specific fact lookups, set chartType and chartData to null.

REPORT DATA:
${context || "(no reports attached yet)"}

Respond with ONLY raw JSON, no markdown fences, no preamble, matching exactly this shape:
{"answer": "string, clear text output", "chartType": "bar" | "pie" | null, "chartTitle": "string or null", "chartData": [{"name": "string", "value": number}] or null}`;
}

function extractChartFromText(text) {
  if (!text) return null;
  const lines = text.split("\n");
  const groupMap = {};
  let currentGroup = null;
  const regex = /[-•*]?\s*([^:\d]+):\s*([\d,]+(?:\.\d+)?)/;

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;

    // Detect category/group headers like "For the Location Based Approach...", "For the Market Based Approach..."
    if (trimmed.includes("Approach") || trimmed.includes("Based") || trimmed.endsWith(":") || trimmed.startsWith("**")) {
      const heading = trimmed.replace(/[\*#_:]/g, "").trim();
      const lower = heading.toLowerCase();
      if (lower.includes("location") || lower.includes("market") || lower.includes("year") || lower.includes("group") || lower.includes("summary")) {
        let cleanGroup = heading.replace(/^For the\s+/i, "").replace(/\s*\(.*?\)/g, "").trim();
        if (lower.includes("location")) cleanGroup = "Location Based";
        if (lower.includes("market")) cleanGroup = "Market Based";
        currentGroup = cleanGroup;
        if (!groupMap[currentGroup]) groupMap[currentGroup] = {};
        continue;
      }
    }

    const match = line.match(regex);
    if (match) {
      const name = match[1].replace(/^[-•*\s]+/, "").trim();
      const val = parseFloat(match[2].replace(/,/g, ""));
      if (!isNaN(val) && val > 0 && name && name.length < 50) {
        const targetGroup = currentGroup || "Default";
        if (!groupMap[targetGroup]) groupMap[targetGroup] = {};
        groupMap[targetGroup][name] = val;
      }
    }
  }

  const groupKeys = Object.keys(groupMap).filter((g) => g !== "Default");

  // If 2+ groups detected (e.g. Location Based vs Market Based), build STACKED BAR CHART!
  if (groupKeys.length >= 2) {
    const allNames = new Set();
    groupKeys.forEach((g) => {
      Object.keys(groupMap[g]).forEach((n) => allNames.add(n));
    });

    const stackedData = Array.from(allNames).map((name) => {
      const row = { name };
      groupKeys.forEach((g) => {
        row[g] = groupMap[g][name] || 0;
      });
      return row;
    });

    return {
      type: "bar",
      stacked: true,
      seriesKeys: groupKeys,
      title: "Scope 2 Emissions Comparison (Stacked Bar Chart)",
      data: stackedData,
    };
  }

  // Single series fallback
  const singleData = [];
  const items = groupMap["Default"] || (groupKeys.length === 1 ? groupMap[groupKeys[0]] : {});
  Object.keys(items).forEach((name) => {
    singleData.push({ name, value: items[name] });
  });

  if (singleData.length >= 2) {
    return {
      type: singleData.length <= 5 ? "pie" : "bar",
      title: "Data Visualization Summary",
      data: singleData.slice(0, 8),
    };
  }

  return null;
}

function parseModelJson(text) {
  const clean = (text || "").replace(/^```json\s*|```$/g, "").trim();
  try {
    const parsed = JSON.parse(clean);
    const ansText = parsed.answer || parsed.text || (typeof parsed === "string" ? parsed : null);

    // First priority: check if text response has multi-approach stacked figures (Location Based vs Market Based)
    let chart = extractChartFromText(ansText);

    if (!chart && parsed.chartData && Array.isArray(parsed.chartData) && parsed.chartData.length > 0) {
      chart = {
        type: parsed.chartType || "bar",
        stacked: parsed.stacked || false,
        seriesKeys: parsed.seriesKeys || null,
        title: parsed.chartTitle || "Data Insights",
        data: parsed.chartData,
      };
    }

    return {
      text: ansText || "Here is the summary of the report data.",
      chart,
    };
  } catch {
    const fallbackText = text || "I couldn't process that just now — try rephrasing your question.";
    return {
      text: fallbackText,
      chart: extractChartFromText(fallbackText),
    };
  }
}

/* The backend is the sole source of truth for answers — it re-reads the
 * actual stored report files and grounds Claude's answer in them. This
 * function no longer contains any hardcoded/fabricated report content;
 * if the backend can't be reached, the person is told that honestly
 * rather than being shown made-up numbers. */
async function askBackend(question, connected, history) {
  if (!connected) {
    return {
      text: "I can't reach the TAXILLA backend service right now, so I don't have access to your reports. " +
            "Please check that the backend is running and try again.",
      chart: null,
    };
  }
  try {
    const resp = await apiFetch(`/api/ask`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ question, history }),
      signal: AbortSignal.timeout(45000),
    });
    if (resp.ok) {
      const { text } = await resp.json();
      return parseModelJson(text);
    }
  } catch { /* fall through */ }
  return {
    text: "Something went wrong reaching the assistant service. Please try again in a moment.",
    chart: null,
  };
}

async function askAssistant(question, files, settings, connected, vizOn = true, history = []) {
  let res = await askBackend(question, connected, history);

  if (vizOn && res) {
    if (!res.chart && res.text) {
      res.chart = extractChartFromText(res.text);
    }
    if (!res.chart && files && files.length > 0 && files[0].sheets) {
      res.chart = autoChartFromSheets(files[0].sheets);
    }
  }

  // Respect Visualization Setting: if visualization is disabled, strip chart
  if (!vizOn && res) {
    res = { ...res, chart: null };
  }

  return res;
}

