const STACK_COLORS = ["#059669", "#6366F1", "#F59E0B", "#0284C7", "#8B5CF6", "#EC4899", "#14B8A6"];

function ChartBlock({ chart, height = 230, showAxisLabels = false }) {
  if (!chart || !chart.data || !chart.data.length) return null;

  // Detect series keys if object has multi-key values (e.g. { name, "Location Based": 303, "Market Based": 916 })
  const seriesKeys = chart.seriesKeys || Object.keys(chart.data[0] || {}).filter((k) => k !== "name" && k !== "value");
  const isStacked = chart.stacked || chart.type === "stacked_bar" || (seriesKeys.length > 0 && chart.type !== "line" && chart.type !== "pie");
  const activeType = chart.type || (isStacked ? "stacked_bar" : "bar");

  const formatNumber = (val) => {
    if (typeof val !== "number") return val;
    if (val >= 1000000) return (val / 1000000).toFixed(1) + "M";
    if (val >= 1000) return (val / 1000).toFixed(0) + "k";
    return val.toLocaleString();
  };

  return (
    <div className="w-full" style={{ height }}>
      <ResponsiveContainer width="100%" height="100%">
        {activeType === "pie" ? (
          <PieChart>
            <Pie data={chart.data} dataKey={seriesKeys.length > 0 ? seriesKeys[0] : "value"} nameKey="name" cx="50%" cy="50%" innerRadius="40%" outerRadius="80%" paddingAngle={2}>
              {chart.data.map((_, i) => <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
            </Pie>
            <Legend layout="vertical" align="right" verticalAlign="middle" iconType="circle" wrapperStyle={{ fontSize: 10.5, color: BRAND.ink }} />
            <Tooltip formatter={(value) => [typeof value === "number" ? value.toLocaleString() : value, "Value"]} />
          </PieChart>
        ) : activeType === "line" ? (
          <LineChart data={chart.data} margin={{ top: 20, right: 15, left: -5, bottom: showAxisLabels ? 45 : 0 }}>
            <CartesianGrid vertical={false} stroke={BRAND.line} />
            <XAxis dataKey="name" tick={{ fontSize: 10, fill: BRAND.sub }} tickLine={false} axisLine={{ stroke: BRAND.line }} />
            <YAxis tick={{ fontSize: 10, fill: BRAND.sub }} axisLine={false} tickLine={false} tickFormatter={formatNumber} />
            <Tooltip formatter={(val, name) => [typeof val === "number" ? val.toLocaleString() : val, name]} />
            {seriesKeys.length > 0 && <Legend wrapperStyle={{ fontSize: 10.5, paddingTop: 4 }} iconType="circle" />}
            {seriesKeys.length > 0 ? (
              seriesKeys.map((key, i) => (
                <Line key={key} type="monotone" dataKey={key} stroke={STACK_COLORS[i % STACK_COLORS.length]} strokeWidth={2.2} dot={{ r: 3 }} />
              ))
            ) : (
              <Line type="monotone" dataKey="value" stroke={STACK_COLORS[0]} strokeWidth={2.2} dot={{ r: 3 }} />
            )}
          </LineChart>
        ) : isStacked ? (
          /* Stacked Bar Chart for multi-category comparative metrics */
          <BarChart data={chart.data} margin={{ top: 20, right: 15, left: -5, bottom: showAxisLabels ? 45 : 0 }}>
            <CartesianGrid vertical={false} stroke={BRAND.line} />
            <XAxis dataKey="name" tick={{ fontSize: 10, fill: BRAND.sub }} axisLine={{ stroke: BRAND.line }} tickLine={false} />
            <YAxis tick={{ fontSize: 10, fill: BRAND.sub }} axisLine={false} tickLine={false} tickFormatter={formatNumber} />
            <Tooltip formatter={(val, name) => [typeof val === "number" ? val.toLocaleString() : val, name]} />
            <Legend wrapperStyle={{ fontSize: 10.5, paddingTop: 4 }} iconType="circle" />
            {seriesKeys.map((key, i) => (
              <Bar key={key} dataKey={key} stackId="a" fill={STACK_COLORS[i % STACK_COLORS.length]} radius={i === seriesKeys.length - 1 ? [4, 4, 0, 0] : [0, 0, 0, 0]} />
            ))}
          </BarChart>
        ) : (
          /* Standard Bar Chart for single series metrics */
          <BarChart data={chart.data} margin={{ top: 20, right: 15, left: -5, bottom: showAxisLabels ? 45 : 0 }}>
            <CartesianGrid vertical={false} stroke={BRAND.line} />
            <XAxis dataKey="name" tick={{ fontSize: 10, fill: BRAND.sub }} axisLine={{ stroke: BRAND.line }} tickLine={false} />
            <YAxis tick={{ fontSize: 10, fill: BRAND.sub }} axisLine={false} tickLine={false} tickFormatter={formatNumber} />
            <Tooltip formatter={(val, name) => [typeof val === "number" ? val.toLocaleString() : val, name]} />
            <Bar dataKey="value" radius={[4, 4, 0, 0]}>
              {chart.data.map((_, i) => <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
            </Bar>
          </BarChart>
        )}
      </ResponsiveContainer>
    </div>
  );
}

function handleDownloadChart(chart) {
  if (!chart || !chart.data || !chart.data.length) return;
  const keys = Object.keys(chart.data[0]);
  const header = keys.join(",");
  const rows = chart.data.map((row) => keys.map((k) => `"${row[k] ?? ""}"`).join(","));
  const csvContent = "data:text/csv;charset=utf-8," + [header, ...rows].join("\n");
  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  link.setAttribute("href", encodedUri);
  link.setAttribute("download", `${(chart.title || "chart_data").replace(/[^a-z0-9]/gi, "_").toLowerCase()}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}

function ChartCard({ chart }) {
  return (
    <div className="rounded-xl border bg-white p-4 space-y-2.5" style={{ borderColor: BRAND.line }}>
      <div className="mb-1">
        <h4 className="text-[13px] font-semibold text-gray-900">{chart.title}</h4>
      </div>
      <ChartBlock chart={chart} />
    </div>
  );
}

