/* Main app                                                             */
/* ------------------------------------------------------------------ */
export default function TaxillaChatbot() {
  const [activeTab, setActiveTab] = useState("chatbot");
  const [files, setFiles] = useState(INITIAL_FILES);
  const [messages, setMessages] = useState(INITIAL_MESSAGES);
  const [input, setInput] = useState("");
  const [vizOn, setVizOn] = useState(true);
  const [sending, setSending] = useState(false);
  const [previewFile, setPreviewFile] = useState(null);
  const [expandChart, setExpandChart] = useState(null);
  const [connected, setConnected] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [platformName, setPlatformName] = useState("TAXILLA");
  const [appName, setAppName] = useState("FT Reconciliation Apps");
  const [locationName, setLocationName] = useState("Taxilla HQ");
  const [pageTitle, setPageTitle] = useState("TAXILLA AI Chatbot");
  const [aiSettings, setAiSettings] = useState({});
  const [search, setSearch] = useState("");
  const [selectMode, setSelectMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState(new Set());
  const [bulkDeleting, setBulkDeleting] = useState(false);
  const fileInputRef = useRef(null);
  const scrollRef = useRef(null);

  const visibleFiles = search.trim()
    ? files.filter((f) => f.name.toLowerCase().includes(search.trim().toLowerCase()))
    : files;

  const lastChart = [...messages].reverse().find((m) => m.chart)?.chart || null;

  const suggestedQuestions = React.useMemo(() => {
    if (!files || files.length === 0) {
      return [
        "Summarize overall reconciliation metrics and key totals",
        "Compare emissions and energy consumption quantities",
        "What is the total utility cost and expense breakdown?",
        "Summarize overall transaction volume and summary",
      ];
    }

    const primaryFile = files[0];
    let columnNames = [];
    if (primaryFile.sheets) {
      const sheetNames = Object.keys(primaryFile.sheets);
      for (const name of sheetNames) {
        const rows = primaryFile.sheets[name];
        if (rows && rows.length > 0) {
          columnNames.push(...Object.keys(rows[0] || {}));
        }
      }
    }

    const textContext = ((primaryFile.csvContext || "") + " " + columnNames.join(" ") + " " + (primaryFile.name || "")).toLowerCase();
    const list = [];

    if (textContext.includes("emission") || textContext.includes("scope") || textContext.includes("co2") || textContext.includes("energy")) {
      list.push("Summarize Scope 2 emissions by utility type");
      list.push("Compare location vs market based emissions");
      list.push("What is the energy consumption and cost breakdown?");
    } else if (textContext.includes("vendor") || textContext.includes("supplier") || textContext.includes("payee")) {
      list.push("Summarize vendor balances and transaction totals");
      list.push("What is the breakdown of top vendor line-item amounts?");
    } else if (textContext.includes("tax") || textContext.includes("gst") || textContext.includes("vat")) {
      list.push("Summarize tax liability and return totals");
      list.push("Compare monthly GST / tax reconciliation variances");
    } else {
      list.push("Summarize transaction metrics and primary totals");
      list.push("Compare key statistical reconciliation figures");
    }

    if (textContext.includes("cost") || textContext.includes("amount") || textContext.includes("price") || textContext.includes("val")) {
      list.push("What is the cost distribution and total quantities?");
    } else {
      list.push("What is the overall transaction volume and summary?");
    }

    list.push("Summarize variance and reconciliation trends across active reports");

    return Array.from(new Set(list)).slice(0, 4);
  }, [files]);

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: "smooth" });
  }, [messages, sending]);

  const hydrateFile = useCallback(async (id, fileLike) => {
    try {
      const { sheets, csvContext } = await parseSpreadsheetFile(fileLike);
      setFiles((prev) => prev.map((p) => (p.id === id ? { ...p, sheets, csvContext, parsed: true } : p)));
    } catch {
      setFiles((prev) => prev.map((p) => (p.id === id ? { ...p, parsed: true } : p)));
    }
  }, []);

  useEffect(() => {
    let unmounted = false;

    const checkAndLoad = () => {
      apiHealth().then((ok) => {
        if (unmounted) return;
        setConnected((prev) => (prev !== ok ? ok : prev));
        if (ok) {
          apiListReports().then((list) => {
            if (unmounted || !list.length) return;
            const mapped = list.map(entryToFile);
            setFiles((prev) => {
              // Don't clobber files the person is actively previewing/parsing —
              // only replace if the set of ids actually changed.
              const prevIds = prev.map((p) => p.id).sort().join(",");
              const nextIds = mapped.map((p) => p.id).sort().join(",");
              return prevIds === nextIds ? prev : mapped;
            });
            mapped.forEach(async (f) => {
              try {
                const res = await fetch(f.downloadUrl);
                const blob = await res.blob();
                await hydrateFile(f.id, new File([blob], f.name));
              } catch { /* ignore */ }
            });
          }).catch(() => {});
        }
      });
    };

    checkAndLoad();
    // Re-check periodically in case the backend starts up after the page
    // has already loaded — otherwise "connected" would stay stuck at false.
    const interval = setInterval(checkAndLoad, 15000);
    return () => { unmounted = true; clearInterval(interval); };
  }, [hydrateFile]);

  const addFilesFromInput = useCallback(async (fileList) => {
    const arr = Array.from(fileList || []);
    // Re-check live rather than trusting potentially-stale `connected` state —
    // the backend may have come up after the page first loaded.
    const liveConnected = await apiHealth();
    if (liveConnected !== connected) setConnected(liveConnected);

    for (const f of arr) {
      if (liveConnected) {
        try {
          const entry = await apiUpload(f);
          const mapped = entryToFile(entry);
          setFiles((prev) => [mapped, ...prev]);
          hydrateFile(mapped.id, f);
          continue;
        } catch {
          setMessages((prev) => [...prev, {
            id: crypto.randomUUID(), role: "bot", time: nowTime(),
            text: `"${f.name}" couldn't be uploaded to the backend (upload failed). It won't be available for questions until it's uploaded successfully — please try again.`,
          }]);
          continue;
        }
      }
      const ext = fileExt(f.name);
      const entry = {
        id: crypto.randomUUID(),
        name: f.name,
        ext,
        size: fmtSize(f.size),
        date: new Date().toLocaleString([], { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }),
        source: "upload",
        blobUrl: URL.createObjectURL(f),
        parsed: false,
        sheets: null,
        csvContext: null,
      };
      setFiles((prev) => [entry, ...prev]);
      hydrateFile(entry.id, f);
      setMessages((prev) => [...prev, {
        id: crypto.randomUUID(), role: "bot", time: nowTime(),
        text: `"${f.name}" was added for preview only — the backend isn't reachable right now, so I can't use it to answer questions until it's connected and the file is re-uploaded.`,
      }]);
    }
  }, [connected, hydrateFile]);

  const handleSend = async (customText = null) => {
    const text = (customText !== null ? customText : input).trim();
    if (!text || sending) return;
    setInput("");
    const userMsg = { id: crypto.randomUUID(), role: "user", time: nowTime(), text };
    setMessages((prev) => [...prev, userMsg]);
    setSending(true);

      try {
      const history = messages
        .filter((m) => m.role === "user" || m.role === "bot")
        .slice(-12)
        .reduce((pairs, m, i, arr) => {
          if (m.role === "user" && arr[i + 1]?.role === "bot") {
            pairs.push({ question: m.text, answer: arr[i + 1].text });
          }
          return pairs;
        }, []);
      const res = await askAssistant(text, files, aiSettings, connected, vizOn, history);
      setMessages((prev) => [
        ...prev,
        {
          id: crypto.randomUUID(),
          role: "bot",
          time: nowTime(),
          text: res.text || "Here's what I found from your reports.",
          chart: res.chart || null,
        },
      ]);
    } catch {
      setMessages((prev) => [...prev, { id: crypto.randomUUID(), role: "bot", time: nowTime(), text: "Something went wrong reaching the assistant. Please try again." }]);
    } finally {
      setSending(false);
    }
  };

  const checkMailbox = async () => {
    if (!connected) {
      setMessages((prev) => [...prev, { id: crypto.randomUUID(), role: "bot", time: nowTime(), text: "Demo mode — not connected to the mailbox sync service. Run backend to sync live Gmail/Outlook attachments." }]);
      return;
    }
    setSyncing(true);
    try {
      const { results } = await apiSync();
      const newCount = (results || []).reduce((sum, r) => sum + (r.newReports || 0), 0);
      const list = await apiListReports();
      const mapped = list.map(entryToFile);
      setFiles(mapped);
      mapped.forEach(async (f) => {
        try {
          const res = await fetch(f.downloadUrl);
          const blob = await res.blob();
          await hydrateFile(f.id, new File([blob], f.name));
        } catch { /* ignore */ }
      });
      setMessages((prev) => [...prev, { id: crypto.randomUUID(), role: "bot", time: nowTime(), text: newCount > 0 ? `Mailbox synced — ${newCount} new report(s) found.` : "Mailbox synced — no new reports since the last check." }]);
    } catch {
      setMessages((prev) => [...prev, { id: crypto.randomUUID(), role: "bot", time: nowTime(), text: "Couldn't reach the mailbox sync service just now — try again shortly." }]);
    } finally {
      setSyncing(false);
    }
  };
    const deleteOneReport = async (id) => {
    try {
      if (connected) {
        await apiFetch(`/api/reports/delete`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ids: [id] }),
        });
      }
    } catch { /* still remove from UI even if backend call failed */ }
    setFiles((prev) => prev.filter((item) => item.id !== id));
  };

  const deleteSelectedReports = async () => {
    const ids = Array.from(selectedIds);
    if (!ids.length) return;
    setBulkDeleting(true);
    try {
      if (connected) {
        await apiFetch(`/api/reports/delete`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ids }),
        });
      }
    } catch { /* still remove from UI even if backend call failed */ } finally {
      setFiles((prev) => prev.filter((item) => !selectedIds.has(item.id)));
      setSelectedIds(new Set());
      setSelectMode(false);
      setBulkDeleting(false);
    }
  };

  return (
    <div
      className="flex h-screen w-full flex-col overflow-hidden bg-cover bg-center"
      style={{ borderColor: BRAND.line, backgroundImage: `url(${APP_BG})`, backgroundColor: "#EEF3FB", fontFamily: "Inter, system-ui, sans-serif" }}
    >
      <TopBar
        onOpenSettings={() => setSettingsOpen(true)}
        onOpenMailConfig={() => setActiveTab("email_processor")}
        platformName={platformName}
        setPlatformName={setPlatformName}
        appName={appName}
        setAppName={setAppName}
      />
      <div className="flex min-h-0 flex-1">
        <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} onOpenSettings={() => setSettingsOpen(true)} />

        <div className="flex min-w-0 flex-1 flex-col overflow-hidden pl-0.5">
          <PageHeader
            pageTitle={activeTab === "email_processor" ? "Email Report Processor" : pageTitle}
            setPageTitle={setPageTitle}
            search={search}
            setSearch={setSearch}
          />

          {activeTab === "email_processor" ? (
            <EmailProcessorView
              onBack={() => setActiveTab("chatbot")}
              aiSettings={aiSettings}
              setAiSettings={setAiSettings}
              onOpenSettings={() => setSettingsOpen(true)}
            />
          ) : activeTab === "transactions" ? (
            <TransactionsView onLaunchChatbot={() => setActiveTab("chatbot")} />
          ) : (
            <div className="flex min-h-0 flex-1 gap-4 overflow-hidden p-4">
        {/* Center — chat */}
        <div className="flex min-w-0 flex-[1.6] flex-col overflow-hidden rounded-[5px] border bg-white" style={{ borderColor: BRAND.line }}>
          <div className="flex items-center justify-between border-b px-5 py-3" style={{ borderColor: BRAND.line }}>
            <div className="flex items-center gap-2.5">
              <Sparkles size={18} color={BRAND.green} />
              <div>
                <div className="text-[14px] font-semibold" style={{ color: BRAND.ink }}>TAXILLA AI Assistant</div>
                <div className="text-[11.5px] text-gray-400">Your intelligent assistant to answer questions from reports</div>
              </div>
            </div>
            <button
              onClick={() => setMessages(INITIAL_MESSAGES)}
              className="flex items-center gap-1.5 rounded-[5px] border px-3 py-1.5 text-[12.5px] font-medium"
              style={{ borderColor: BRAND.greenBorder, color: BRAND.greenDark }}
            >
              <Trash2 size={13} /> Clear Chat
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 space-y-3 overflow-y-auto px-5 py-4">
            {messages.map((m) => (
              <div key={m.id} className={`flex ${m.role === "user" ? "justify-end" : "justify-start"}`}>
                <div className={`max-w-[75%] ${m.role === "user" ? "" : "w-full max-w-[560px]"}`}>
                  <div
                    className={`rounded-[5px] px-4 py-2.5 text-[13.5px] leading-relaxed ${m.role === "user" ? "whitespace-pre-line" : ""}`}
                    style={m.role === "user" ? { background: BRAND.greenSoft, color: BRAND.ink } : { background: "white", color: BRAND.ink, border: `1px solid ${BRAND.line}` }}
                  >
                    {m.role === "user" ? m.text : <MarkdownMessage text={m.text} />}
                  </div>
                  <div className={`mt-1 flex items-center gap-1 text-[10.5px] text-gray-400 ${m.role === "user" ? "justify-end" : ""}`}>
                    {m.time} {m.role === "user" && <Check size={12} color={BRAND.green} />}
                  </div>
                </div>
              </div>
            ))}
            {sending && (
              <div className="flex justify-start">
                <div className="flex items-center gap-2 rounded-[5px] border bg-white px-4 py-2.5 text-[13px] text-gray-400" style={{ borderColor: BRAND.line }}>
                  <Loader2 size={14} className="animate-spin" /> Analyzing TAXILLA System Reports…
                </div>
              </div>
            )}
          </div>

          <div className="border-t bg-white px-5 py-3 space-y-2.5" style={{ borderColor: BRAND.line }}>
            {/* Predefined Questions Bar */}
            <div className="flex items-center gap-1.5 overflow-x-auto pb-1 no-scrollbar" style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}>
              {suggestedQuestions.map((q, idx) => (
                <button
                  key={idx}
                  type="button"
                  onClick={() => handleSend(q)}
                  className="shrink-0 rounded-full border bg-gray-50 px-3 py-1 text-[11.5px] font-medium text-gray-700 hover:bg-green-50 hover:text-green-800 hover:border-green-300 transition-colors cursor-pointer"
                  style={{ borderColor: BRAND.line }}
                >
                  {q}
                </button>
              ))}
            </div>

            <div className="flex items-center gap-2 rounded-[5px] border px-3 py-2" style={{ borderColor: BRAND.line }}>
              <button onClick={() => fileInputRef.current?.click()} className="text-gray-400 hover:text-gray-600 shrink-0" title="Upload System Report File">
                <Paperclip size={17} />
              </button>
              <input
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleSend()}
                placeholder="Ask a question about TAXILLA reports..."
                className="flex-1 bg-transparent text-[13.5px] outline-none placeholder:text-gray-400"
              />
              <button onClick={() => handleSend()} disabled={sending || !input.trim()} className="flex h-8 w-8 items-center justify-center rounded-[5px] text-white disabled:opacity-40" style={{ background: BRAND.green }}>
                <Send size={15} />
              </button>
            </div>
            <input id="hidden-file-input" ref={fileInputRef} type="file" multiple hidden accept=".xlsx,.xls,.csv,.pdf" onChange={(e) => addFilesFromInput(e.target.files)} />
          </div>
        </div>

        {/* Right — visualization + reports */}
        <div className="flex w-[340px] shrink-0 flex-col gap-4 overflow-y-auto">
          {/* 1. Visualization */}
          <div className="rounded-[5px] border bg-white p-4" style={{ borderColor: BRAND.line }}>
            <div className="mb-3 flex items-center justify-between">
              <div className="flex items-center gap-1.5 text-[13.5px] font-semibold" style={{ color: BRAND.ink }}>
                <BarChartIcon size={14} /> Visualization
              </div>
              <div className="flex items-center gap-2 text-gray-400">
                <button
                  onClick={() => lastChart && setExpandChart(lastChart)}
                  disabled={!lastChart}
                  className="hover:text-gray-600 disabled:opacity-30 cursor-pointer transition-colors"
                  title="Maximize Visualization"
                >
                  <Maximize2 size={14} />
                </button>
                <button
                  onClick={() => lastChart && handleDownloadChart(lastChart)}
                  disabled={!lastChart}
                  className="hover:text-gray-600 disabled:opacity-30 cursor-pointer transition-colors"
                  title="Download Chart Data (CSV)"
                >
                  <Download size={14} />
                </button>
              </div>
            </div>
            {vizOn && lastChart ? (
              <ChartCard chart={lastChart} />
            ) : (
              <div className="rounded-[5px] border border-dashed py-8 text-center text-[12px] text-gray-400" style={{ borderColor: BRAND.line }}>
                {vizOn ? "Ask a question to see a chart here." : "Visualization is turned off in Settings."}
              </div>
            )}
          </div>

          {/* 2. Attached Reports */}
          <div className="rounded-[5px] border bg-white p-4" style={{ borderColor: BRAND.line }}>
            <div className="mb-3 flex items-center justify-between">
              <div className="flex items-center gap-1.5 text-[13.5px] font-semibold" style={{ color: BRAND.ink }}>
                <Paperclip size={14} /> TAXILLA System Reports
              </div>
              <div className="flex items-center gap-2">
                <span className="rounded-full px-2 py-0.5 text-[10px] font-medium" style={{ background: connected ? BRAND.greenSoft : "#F3F4F6", color: connected ? BRAND.greenDark : "#9CA3AF" }}>
                  {connected ? "● System Active" : "Demo Mode"}
                </span>
                <button
                  onClick={() => { setSelectMode((v) => !v); setSelectedIds(new Set()); }}
                  className="text-[12px] font-medium"
                  style={{ color: selectMode ? BRAND.blue : BRAND.green }}
                >
                  {selectMode ? "Cancel" : "Select"}
                </button>
                {selectMode && (
                  <button
                    onClick={() => {
                      const allIds = visibleFiles.map((f) => f.id);
                      setSelectedIds((prev) =>
                        prev.size === allIds.length ? new Set() : new Set(allIds)
                      );
                    }}
                    className="text-[12px] font-medium"
                    style={{ color: BRAND.green }}
                  >
                    {selectedIds.size === visibleFiles.length ? "Deselect All" : "Select All"}
                  </button>
                )}
              </div>
            </div>

            {selectMode && selectedIds.size > 0 && (
              <button
                onClick={deleteSelectedReports}
                disabled={bulkDeleting}
                className="mb-3 flex w-full items-center justify-center gap-1.5 rounded-[5px] py-2 text-[12.5px] font-medium text-white disabled:opacity-60"
                style={{ background: "#DC2626" }}
              >
                {bulkDeleting ? <Loader2 size={13.5} className="animate-spin" /> : <Trash2 size={13.5} />}
                {bulkDeleting ? "Deleting…" : `Delete ${selectedIds.size} selected`}
              </button>
            )}

            {!selectMode && (
              <button
                onClick={() => fileInputRef.current?.click()}
                className="mb-3 flex w-full items-center justify-center gap-2 rounded-[5px] border border-dashed py-2.5 text-[12.5px] font-medium"
                style={{ borderColor: BRAND.greenBorder, color: BRAND.greenDark, background: BRAND.greenSoft }}
              >
                <UploadCloud size={15} /> Upload file
              </button>
            )}
            <div className="space-y-2.5">
              {visibleFiles.length === 0 && (
                <div className="rounded-[5px] border border-dashed p-4 text-center text-[12px] text-gray-400" style={{ borderColor: BRAND.line }}>
                  {connected
                    ? "No reports yet. Upload one or run a mailbox sync."
                    : "Backend not connected — reports fetched from Gmail/Outlook or uploaded will appear here once it's running."}
                </div>
              )}
              {visibleFiles.map((f) => (
                <div key={f.id} className="flex items-start gap-2.5 rounded-[5px] border p-2.5" style={{ borderColor: BRAND.line }}>
                  {selectMode && (
                    <input
                      type="checkbox"
                      className="mt-1 accent-green-600"
                      checked={selectedIds.has(f.id)}
                      onChange={(e) => {
                        setSelectedIds((prev) => {
                          const next = new Set(prev);
                          e.target.checked ? next.add(f.id) : next.delete(f.id);
                          return next;
                        });
                      }}
                    />
                  )}
                  <FileIcon ext={f.ext} />
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-[12.5px] font-medium" style={{ color: BRAND.ink }} title={f.name}>{f.name}</div>
                    <div className="mt-0.5 flex items-center gap-1 text-[11px] text-gray-400">
                      <span className="uppercase">{f.ext}</span>
                      {f.size && <><span>•</span><span>{f.size}</span></>}
                      <span>•</span>
                      <span>{f.date}</span>
                    </div>
                    <div className="mt-0.5 flex items-center gap-1 text-[10.5px]" style={{ color: f.source === "upload" ? BRAND.greenDark : BRAND.blue }}>
                      {f.source === "upload" ? <UploadCloud size={10} /> : <Mail size={10} />}
                      {sourceLabel(f.source)}
                      {!f.parsed && <Loader2 size={10} className="animate-spin ml-1" />}
                    </div>
                  </div>
                  {!selectMode && (
                    <div className="flex shrink-0 flex-col items-center gap-1.5 pt-0.5 text-gray-400">
                      <button onClick={() => setPreviewFile(f)} className="hover:text-gray-700" title="Preview"><Eye size={14} /></button>
                      <button
                        onClick={() => {
                          const url = f.downloadUrl || f.blobUrl;
                          if (url) { const a = document.createElement("a"); a.href = url; a.download = f.name; a.click(); }
                        }}
                        className="hover:text-gray-700"
                        title="Download"
                      >
                        <Download size={14} />
                      </button>
                      <button
                        onClick={() => deleteOneReport(f.id)}
                        className="hover:text-red-600 transition-colors"
                        title="Delete report"
                      >
                        <Trash2 size={13.5} />
                      </button>
                    </div>
                  )}
                </div>
              ))}
            </div>

            <button onClick={checkMailbox} disabled={syncing} className="mt-3 flex w-full items-center justify-center gap-1.5 text-[11.5px] text-gray-400 hover:text-gray-600 disabled:opacity-60">
              {syncing ? <Loader2 size={12} className="animate-spin" /> : <Mail size={12} />}
              {syncing ? "Syncing…" : "Check mailbox"}
            </button>
          </div>
        </div>
      </div>
      )}
        </div>
      </div>

      {settingsOpen && (
        <SettingsModal
          vizOn={vizOn}
          setVizOn={setVizOn}
          aiSettings={aiSettings}
          setAiSettings={setAiSettings}
          platformName={platformName}
          setPlatformName={setPlatformName}
          appName={appName}
          setAppName={setAppName}
          onClose={() => setSettingsOpen(false)}
        />
      )}

      {/* File preview modal */}
      {previewFile && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-6" onClick={() => setPreviewFile(null)}>
          <div className="max-h-[80vh] w-full max-w-2xl overflow-hidden rounded-xl bg-white" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between border-b px-4 py-3" style={{ borderColor: BRAND.line }}>
              <div className="text-[13.5px] font-semibold" style={{ color: BRAND.ink }}>{previewFile.name}</div>
              <button onClick={() => setPreviewFile(null)} className="text-gray-400 hover:text-gray-600"><X size={16} /></button>
            </div>
            <div className="max-h-[65vh] overflow-auto p-4">
              {previewFile.sheets ? (
                Object.entries(previewFile.sheets).map(([sheetName, rows]) => (
                  <div key={sheetName} className="mb-4">
                    <div className="mb-1 text-[12px] font-semibold text-gray-500">{sheetName}</div>
                    {rows.length ? (
                      <table className="w-full border-collapse text-[11.5px]">
                        <thead>
                          <tr>{Object.keys(rows[0]).map((h) => <th key={h} className="border-b px-2 py-1 text-left font-semibold" style={{ borderColor: BRAND.line, color: BRAND.ink }}>{h}</th>)}</tr>
                        </thead>
                        <tbody>
                          {rows.slice(0, 15).map((r, i) => (
                            <tr key={i}>{Object.keys(rows[0]).map((h) => <td key={h} className="border-b px-2 py-1 text-gray-600" style={{ borderColor: BRAND.line }}>{String(r[h] ?? "")}</td>)}</tr>
                          ))}
                        </tbody>
                      </table>
                    ) : <div className="text-[12px] text-gray-400">No rows found.</div>}
                  </div>
                ))
              ) : (
                <div className="text-[12.5px] text-gray-400">
                  {previewFile.ext === "pdf"
                    ? "PDF text isn't extracted in the browser. Add a PDF-parsing step to the backend service (e.g. pdfplumber) so its text/tables land in index.json alongside the file, the same way spreadsheet rows do."
                    : "This file hasn't finished parsing yet."}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Chart expand modal */}
      {expandChart && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-6" onClick={() => setExpandChart(null)}>
          <div className="w-full max-w-4xl rounded-xl bg-white p-5" onClick={(e) => e.stopPropagation()}>
            <div className="mb-3 flex items-center justify-between">
              <div className="text-[14px] font-semibold" style={{ color: BRAND.ink }}>{expandChart.title}</div>
              <button onClick={() => setExpandChart(null)} className="text-gray-400 hover:text-gray-600"><X size={16} /></button>
            </div>
            <ChartBlock chart={expandChart} height={400} showAxisLabels={true} />
          </div>
        </div>
      )}
    </div>
  );
}
